-- Importação: Chamados Abertos GIP → OnLight (produção)
-- Fonte: Chamados Abertos GIP.xlsx
-- Gerado em: 2026-08-01 08:44
-- =============================================================================
-- Conteúdo:
--   - 252 chamados (OS com número; linhas vazias ignoradas)
--   - 9 com CPF válido | 243 sem CPF (endereço mantido)
--   - prioridade = Normal | status = Aberto
--   - aberto_em / data_abertura_os = HOJE (NOW / CURDATE)
--   - na descricao: [GIP:<OS> | Abertura GIP: dd/mm/aaaa] (data da planilha)
--   - origem_os = Importação GIP | problema_os = Ponto Apagado | tipo_os = Corretiva
-- =============================================================================

SET NAMES utf8mb4;

START TRANSACTION;

-- >>> AJUSTE AQUI se necessário (ex.: SET @cid := 1;)
SET @cid := (
    SELECT id FROM clientes
    WHERE nome LIKE '%Ipojuca%' OR empresa LIKE '%Ipojuca%'
    ORDER BY id ASC
    LIMIT 1
);
SET @cid := COALESCE(@cid, (SELECT id FROM clientes ORDER BY id ASC LIMIT 1));

SELECT @cid AS cliente_id_usado;

INSERT INTO chamados (
    cliente_id, titulo, descricao,
    contribuinte_cpf, contribuinte_nome,
    data_abertura_os, origem_os, problema_os, tipo_os,
    os_logradouro, os_bairro, os_cidade, os_uf,
    endereco_completo, prioridade, status, responsavel, aberto_em
)
