-- Conferência
SELECT COUNT(*) AS importados_gip
FROM chamados
WHERE descricao LIKE '%[GIP:%';

SELECT id, titulo, contribuinte_cpf, contribuinte_nome, os_bairro, aberto_em, prioridade, status, LEFT(descricao, 180) AS descricao
FROM chamados
WHERE descricao LIKE '%[GIP:%'
ORDER BY id DESC
LIMIT 20;

